+            description: 'Opaque pagination cursor returned by a previous call.'
+          },
+          page_size: {
+            type: 'integer',
+            minimum: MIN_PAGE_SIZE,
+            maximum: MAX_PAGE_SIZE,
+            description: 'Number of events per page (1-3, default 2).'
+          }
+        },
+        required: [],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (args === null || args === undefined) args = {};
+
+  if (name !== 'events_list') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  const allowed = new Set(['cursor', 'page_size']);
+  for (const key of Object.keys(args)) {
+    if (!allowed.has(key)) {
+      throw new Error('Unknown argument: ' + key);
+    }
+  }
+
+  let start = 0;
+  if (args.cursor !== undefined) {
+    if (typeof args.cursor !== 'string') {
+      throw new Error('cursor must be a string');
+    }
+    start = decodeCursor(args.cursor);
+  }
+
+  let pageSize = DEFAULT_PAGE_SIZE;
+  if (args.page_size !== undefined) {
+    if (
+      !Number.isInteger(args.page_size) ||
+      args.page_size < MIN_PAGE_SIZE ||
+      args.page_size > MAX_PAGE_SIZE
+    ) {
